import hashlib
import hmac
import os
import time
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)
app.config['DATABASE'] = ':memory:'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.execute('CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT, expires_at REAL)')
        g.db.execute('CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, role TEXT, email TEXT)')
        g.db.commit()
    return g.db

def generate_token(user_id):
    """Generate a secure session token with HMAC binding."""
    nonce = os.urandom(16).hex()
    timestamp = str(int(time.time()))
    payload = f"{user_id}:{timestamp}:{nonce}"
    mac = hmac.new(app.config['SECRET_KEY'], payload.encode('utf-8'), hashlib.sha256).hexdigest()
    token = f"{payload}:{mac}"
    return token

def constant_time_compare(a, b):
    """Perform constant-time comparison to prevent timing attacks.
    Handles both str and bytes inputs safely."""
    if isinstance(a, str):
        a = a.encode('utf-8')
    if isinstance(b, str):
        b = b.encode('utf-8')
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= x ^ y
    return result == 0

def validate_token_mac(token):
    """Validate the HMAC component of a session token."""
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None, "malformed token"
    payload, provided_mac = parts
    expected_mac = hmac.new(app.config['SECRET_KEY'], payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if constant_time_compare(provided_mac, expected_mac):
        return payload, None
    return None, "invalid signature"

def check_session_active(token):
    """Check if session token exists and is not expired."""
    db = get_db()
    # Normalize token for storage lookup
    normalized = token.strip()
    cursor = db.execute('SELECT user_id, expires_at FROM sessions WHERE token = ?', (normalized,))
    row = cursor.fetchone()
    if row is None:
        return None, "session not found"
    user_id, expires_at = row
    if time.time() > expires_at:
        db.execute('DELETE FROM sessions WHERE token = ?', (normalized,))
        db.commit()
        return None, "session expired"
    return user_id, None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'missing token'}), 401
        token = auth_header[7:]
        # First validate MAC integrity
        payload, err = validate_token_mac(token)
        if err:
            return jsonify({'error': err}), 401
        # Then check session is active in database
        user_id, err = check_session_active(token)
        if err:
            return jsonify({'error': err}), 401
        g.current_user = user_id
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        db = get_db()
        cursor = db.execute('SELECT role FROM users WHERE id = ?', (g.current_user,))
        row = cursor.fetchone()
        if row is None or row[0] != 'admin':
            return jsonify({'error': 'forbidden'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'user_id' not in data:
        return jsonify({'error': 'missing user_id'}), 400
    user_id = data['user_id']
    db = get_db()
    # Check user exists
    cursor = db.execute('SELECT id FROM users WHERE id = ?', (user_id,))
    if cursor.fetchone() is None:
        return jsonify({'error': 'user not found'}), 404
    token = generate_token(user_id)
    expires_at = time.time() + 3600
    db.execute('INSERT OR REPLACE INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)',
               (token, user_id, expires_at))
    db.commit()
    return jsonify({'token': token})

@app.route('/api/revoke', methods=['POST'])
@require_auth
def revoke_session():
    """Revoke current session."""
    token = request.headers.get('Authorization', '')[7:]
    db = get_db()
    db.execute('DELETE FROM sessions WHERE token = ?', (token.strip(),))
    db.commit()
    return jsonify({'status': 'revoked'})

@app.route('/api/admin/revoke_user', methods=['POST'])
@require_auth
@require_admin
def admin_revoke_user():
    """Admin endpoint to revoke all sessions for a user."""
    data = request.get_json()
    target_user = data.get('user_id', '')
    db = get_db()
    db.execute('DELETE FROM sessions WHERE user_id = ?', (target_user,))
    db.commit()
    return jsonify({'status': 'all sessions revoked', 'user': target_user})

@app.route('/api/profile')
@require_auth
def get_profile():
    db = get_db()
    cursor = db.execute('SELECT id, role, email FROM users WHERE id = ?', (g.current_user,))
    row = cursor.fetchone()
    if row:
        return jsonify({'id': row[0], 'role': row[1], 'email': row[2]})
    return jsonify({'error': 'not found'}), 404

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(debug=False)
